WITH cleaned AS (SELECT id, order_id, amount, paid_at, status, COALESCE(amount, 0) AS amount_filled, CASE WHEN amount >= 1300 THEN 'High' WHEN amount >= 670 THEN 'Medium' ELSE 'Low' END AS amount_level FROM payments WHERE method IS NOT NULL AND order_id IN (5, 11, 17)) SELECT id, order_id, amount, paid_at, status, amount_filled, MAX(amount) OVER w_grp AS last7_max_amount, MIN(amount) OVER w_grp AS last7_min_amount, AVG(amount) OVER w_grp AS last7_avg_amount, COUNT(amount) OVER w_grp AS last7_count_amount FROM cleaned WHERE order_id IS NULL WINDOW w_grp AS (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW);
